const loader=document.getElementById('loader'),reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;addEventListener('load',()=>setTimeout(()=>{loader.classList.add('is-hidden');document.body.classList.remove('loading');setTimeout(()=>loader.remove(),700)},reduced?150:2200));
const picker=document.getElementById('ride-picker'),modal=document.getElementById('modal'),title=document.getElementById('modal-title'),body=document.getElementById('modal-body'),toast=document.getElementById('toast');const read=k=>JSON.parse(localStorage.getItem(k)||'[]'),write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
function notify(t){toast.textContent=t;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2400)}function showModal(t,c){title.textContent=t;body.innerHTML=c;modal.hidden=false}function closeModal(){modal.hidden=true}document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);
document.querySelectorAll('[data-scroll]').forEach(x=>x.onclick=()=>document.getElementById(x.dataset.scroll).scrollIntoView({behavior:'smooth'}));document.querySelectorAll('[data-mode]').forEach(x=>x.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(b=>b.classList.remove('selected'));x.classList.add('selected');document.getElementById('time-choice').textContent=x.dataset.mode==='schedule'?'Choose date & time':'Pickup now⌄'});document.querySelectorAll('[data-mode-open]').forEach(x=>x.onclick=()=>{document.querySelector('[data-mode="schedule"]').click();document.getElementById('book').scrollIntoView({behavior:'smooth'})});
document.getElementById('see-prices').onclick=()=>{if(!document.getElementById('to').value.trim()){notify('Enter a destination first');document.getElementById('to').focus();return}picker.hidden=false;picker.scrollIntoView({behavior:'smooth'})};document.querySelectorAll('[data-ride]').forEach(x=>x.onclick=()=>{const t={from:document.getElementById('from').value,to:document.getElementById('to').value,ride:x.dataset.ride,price:x.dataset.price,date:new Date().toLocaleString()};const trips=read('safarTrips');trips.unshift(t);write('safarTrips',trips);showModal('Ride requested',`<p><strong>${t.ride} · ${t.price}</strong></p><p>${t.from}<br>to ${t.to}</p><p>Your request is saved on this device. Live dispatch activates when a mobility provider is connected.</p><button class="cta" data-done>Done</button>`);body.querySelector('[data-done]').onclick=closeModal});
document.querySelectorAll('[data-open]').forEach(x=>x.onclick=()=>{const type=x.dataset.open;if(type==='history'){const trips=read('safarTrips');showModal('Your trips',trips.map(t=>`<div class="trip"><strong>${t.from} → ${t.to}</strong><small>${t.ride||'Scheduled'} · ${t.price||''} · ${t.date}</small></div>`).join('')||'<p>No trips on this device yet.</p>')}if(type==='safety')showModal('Safety Centre','<p><strong>Route monitoring</strong><br>Detect unexpected deviations and long stops.</p><p><strong>Trusted contacts</strong><br>Share live trip details with people you choose.</p><p><strong>Emergency help</strong><br>Connect verified local emergency providers before launch.</p>');if(type==='share')showModal('Safar Share','<p>Match with verified travellers whose routes overlap yours. See the exact saving, pickup walk, and added time before you confirm.</p>');if(type==='intercity')showModal('Plan an intercity trip','<input placeholder="Leaving from"><input placeholder="Going to"><button class="cta" data-done>Check routes</button>')});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
